entries.answer:
Yes — your blueprint is buildable as a single self-contained `index.html`, and the one implementation detail I would tighten is the CodeMirror loading strategy: CodeMirror’s own examples use `basicSetup` with `EditorView`, while browser-only CDN setups are more reliable when the ESM imports are pinned and aligned so shared dependencies resolve consistently.[1][2]

## Implementation

Paste this into `index.html` as-is.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>single-file-web-ide</title>
  <style>
    :root {
      color-scheme: dark light;

      --background-root: hsl(225 18% 9%);
      --background-default: hsl(225 16% 12%);
      --background-higher: hsl(225 14% 16%);
      --background-highest: hsl(225 13% 20%);
      --background-overlay: hsl(225 18% 8% / 0.6);

      --foreground-default: hsl(220 15% 92%);
      --foreground-dimmer: hsl(220 11% 71%);
      --foreground-dimmest: hsl(220 10% 52%);

      --outline-dimmest: hsl(220 12% 24%);
      --outline-dimmer: hsl(220 12% 30%);
      --outline-default: hsl(220 13% 40%);
      --outline-stronger: hsl(220 16% 58%);

      --accent-primary-default: hsl(204 100% 62%);
      --accent-primary-hover: hsl(204 100% 68%);
      --accent-primary-active: hsl(204 100% 56%);
      --accent-primary-soft: hsl(204 100% 62% / 0.14);

      --accent-positive-default: hsl(138 77% 42%);
      --accent-positive-soft: hsl(138 77% 42% / 0.14);

      --accent-negative-default: hsl(355 87% 61%);
      --accent-negative-soft: hsl(355 87% 61% / 0.15);

      --accent-blurple-default: hsl(252 88% 73%);
      --accent-blurple-soft: hsl(252 88% 73% / 0.16);

      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 22px;

      --shadow-sm: 0 4px 18px hsl(0 0% 0% / 0.14);
      --shadow-md: 0 14px 36px hsl(0 0% 0% / 0.22);
      --shadow-lg: 0 24px 64px hsl(0 0% 0% / 0.35);

      --space-1: 4px;
      --space-2: 8px;
      --space-3: 12px;
      --space-4: 16px;
      --space-5: 20px;
      --space-6: 24px;
      --space-8: 32px;
      --space-10: 40px;

      --leftbar-width: 48px;
      --left-sidebar-width: 280px;
      --right-sidebar-width: 375px;
      --dock-height: 56px;
      --terminal-height: 220px;

      --font-ui: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

      --transition-fast: 160ms cubic-bezier(.2,.8,.2,1);
      --transition-med: 240ms cubic-bezier(.2,.8,.2,1);
    }

    @media (prefers-color-scheme: light) {
      :root {
        --background-root: hsl(220 20% 96%);
        --background-default: hsl(0 0% 100%);
        --background-higher: hsl(220 16% 96%);
        --background-highest: hsl(220 15% 92%);
        --background-overlay: hsl(220 20% 30% / 0.18);

        --foreground-default: hsl(225 18% 16%);
        --foreground-dimmer: hsl(225 10% 42%);
        --foreground-dimmest: hsl(225 8% 56%);

        --outline-dimmest: hsl(220 18% 88%);
        --outline-dimmer: hsl(220 16% 82%);
        --outline-default: hsl(220 14% 72%);
        --outline-stronger: hsl(220 14% 56%);

        --shadow-sm: 0 6px 18px hsl(220 20% 20% / 0.06);
        --shadow-md: 0 16px 44px hsl(220 22% 20% / 0.10);
        --shadow-lg: 0 28px 76px hsl(220 24% 20% / 0.16);
      }
    }

    html[data-theme="dark"] {
      color-scheme: dark;
    }

    html[data-theme="light"] {
      color-scheme: light;
    }

    * { box-sizing: border-box; }
    html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
    body {
      font-family: var(--font-ui);
      background: var(--background-root);
      color: var(--foreground-default);
      line-height: 1.45;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    button, input, textarea, select {
      font: inherit;
      color: inherit;
    }

    button {
      cursor: pointer;
      border: 0;
      background: none;
      padding: 0;
    }

    input, select, textarea, [contenteditable="true"] {
      background: var(--background-higher);
      border: 1px solid var(--outline-dimmest);
      border-radius: var(--radius-sm);
      color: var(--foreground-default);
      outline: none;
    }

    input:focus, select:focus, textarea:focus, [contenteditable="true"]:focus,
    button:focus-visible, a:focus-visible {
      outline: 2px solid var(--accent-primary-default);
      outline-offset: 2px;
    }

    .skip-link {
      position: absolute;
      left: 16px;
      top: -48px;
      z-index: 1000;
      background: var(--accent-primary-default);
      color: white;
      padding: 10px 14px;
      border-radius: 999px;
      text-decoration: none;
      transition: top var(--transition-fast);
    }

    .skip-link:focus { top: 12px; }

    .app-shell {
      display: flex;
      width: 100vw;
      height: calc(100vh - var(--dock-height));
      overflow: hidden;
    }

    .activity-bar {
      width: var(--leftbar-width);
      min-width: var(--leftbar-width);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: space-between;
      padding: var(--space-2) 0;
      background: linear-gradient(180deg, var(--background-default), var(--background-higher));
      border-right: 1px solid var(--outline-dimmest);
    }

    .activity-group, .activity-meta {
      display: flex;
      flex-direction: column;
      gap: 2px;
      width: 100%;
      align-items: center;
    }

    .activity-btn {
      position: relative;
      width: 100%;
      height: 44px;
      display: grid;
      place-items: center;
      color: var(--foreground-dimmer);
      transition: color var(--transition-fast), background var(--transition-fast);
    }

    .activity-btn:hover { color: var(--foreground-default); background: var(--background-highest); }
    .activity-btn.active { color: var(--foreground-default); }
    .activity-btn.active::before {
      content: "";
      position: absolute;
      left: 0;
      top: 8px;
      bottom: 8px;
      width: 3px;
      border-radius: 0 999px 999px 0;
      background: var(--accent-primary-default);
    }

    .icon {
      width: 20px;
      height: 20px;
      stroke: currentColor;
      stroke-width: 1.75;
      fill: none;
      stroke-linecap: round;
      stroke-linejoin: round;
      pointer-events: none;
    }

    .sidebar-left,
    .sidebar-right {
      background: var(--background-default);
      border-right: 1px solid var(--outline-dimmest);
      overflow: hidden;
      transition: width var(--transition-med), opacity var(--transition-med), transform var(--transition-med);
    }

    .sidebar-left {
      width: var(--left-sidebar-width);
      min-width: 0;
      display: flex;
      flex-direction: column;
    }

    .sidebar-left.collapsed {
      width: 0;
      border-right-color: transparent;
    }

    .sidebar-right {
      width: var(--right-sidebar-width);
      border-right: 0;
      border-left: 1px solid var(--outline-dimmest);
      display: flex;
      flex-direction: column;
    }

    .sidebar-right.collapsed {
      width: 0;
      border-left-color: transparent;
    }

    .workspace {
      flex: 1;
      min-width: 0;
      display: flex;
      flex-direction: column;
      background: var(--background-root);
      overflow: hidden;
    }

    .tabs-bar {
      height: 42px;
      display: flex;
      align-items: stretch;
      justify-content: space-between;
      background: var(--background-default);
      border-bottom: 1px solid var(--outline-dimmest);
      min-width: 0;
    }

    .tabs-list {
      display: flex;
      min-width: 0;
      overflow-x: auto;
      scrollbar-width: none;
    }
    .tabs-list::-webkit-scrollbar { display: none; }

    .tab {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      min-width: 0;
      padding: 0 14px;
      border-right: 1px solid var(--outline-dimmest);
      color: var(--foreground-dimmer);
      background: var(--background-higher);
      transition: background var(--transition-fast), color var(--transition-fast);
    }

    .tab.active {
      color: var(--foreground-default);
      background: var(--background-default);
      box-shadow: inset 0 2px 0 var(--accent-primary-default);
    }

    .tab-name {
      max-width: 160px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      font-size: 13px;
    }

    .tab-close {
      width: 18px;
      height: 18px;
      border-radius: 999px;
      display: grid;
      place-items: center;
      color: var(--foreground-dimmer);
    }

    .tab-close:hover { background: var(--background-highest); color: var(--foreground-default); }

    .editor-toolbar {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 12px;
      border-left: 1px solid var(--outline-dimmest);
      color: var(--foreground-dimmer);
      font-size: 12px;
      white-space: nowrap;
    }

    .editor-stage {
      position: relative;
      flex: 1;
      min-height: 0;
      display: grid;
      grid-template-columns: 1fr;
      overflow: hidden;
      background: var(--background-root);
    }

    .editor-surface {
      display: flex;
      flex-direction: column;
      min-height: 0;
      min-width: 0;
      background: var(--background-default);
    }

    #editorHost {
      flex: 1;
      min-height: 0;
      overflow: auto;
    }

    .editor-status {
      height: 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 0 12px;
      background: var(--background-higher);
      border-top: 1px solid var(--outline-dimmest);
      font-size: 12px;
      color: var(--foreground-dimmer);
    }

    .preview-pane {
      position: absolute;
      inset: 16px 16px 16px 16px;
      background: var(--background-default);
      border: 1px solid var(--outline-dimmer);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      overflow: hidden;
      z-index: 4;
      transform: translateY(16px) scale(.985);
      opacity: 0;
      pointer-events: none;
      transition: transform var(--transition-med), opacity var(--transition-med);
    }

    .preview-pane.open {
      transform: translateY(0) scale(1);
      opacity: 1;
      pointer-events: auto;
    }

    .preview-head {
      height: 42px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 14px;
      border-bottom: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
    }

    .preview-frame {
      width: 100%;
      height: calc(100% - 42px);
      border: 0;
      background: white;
    }

    .terminal-panel {
      height: var(--terminal-height);
      min-height: 0;
      display: flex;
      flex-direction: column;
      background: var(--background-default);
      border-top: 1px solid var(--outline-dimmest);
      transition: height var(--transition-med), opacity var(--transition-med);
    }

    .terminal-panel.collapsed {
      height: 0;
      opacity: 0;
      border-top-color: transparent;
    }

    .terminal-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      min-height: 36px;
      padding: 0 12px;
      border-bottom: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
      color: var(--foreground-dimmer);
      font-size: 12px;
    }

    .terminal-log {
      flex: 1;
      min-height: 0;
      overflow: auto;
      padding: 10px 12px;
      font-family: var(--mono);
      font-size: 12px;
      white-space: pre-wrap;
      color: var(--foreground-default);
    }

    .terminal-line {
      margin-bottom: 6px;
    }

    .terminal-line.dim { color: var(--foreground-dimmer); }
    .terminal-line.ok { color: hsl(138 67% 58%); }
    .terminal-line.err { color: hsl(355 88% 68%); }

    .terminal-input-wrap {
      display: flex;
      align-items: center;
      gap: 8px;
      border-top: 1px solid var(--outline-dimmest);
      padding: 10px 12px;
      background: var(--background-default);
      font-family: var(--mono);
    }

    .terminal-input {
      flex: 1;
      min-width: 0;
      background: transparent;
      border: 0;
      border-radius: 0;
      font-family: inherit;
      padding: 0;
    }

    .panel-wrap {
      display: flex;
      flex-direction: column;
      min-height: 0;
      height: 100%;
    }

    .panel-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 12px 14px;
      border-bottom: 1px solid var(--outline-dimmest);
      background: var(--background-default);
    }

    .panel-title h2,
    .agent-head h2 {
      margin: 0;
      font-size: 14px;
      font-weight: 650;
    }

    .panel-subtle,
    .muted {
      color: var(--foreground-dimmer);
      font-size: 12px;
    }

    .panel-body {
      flex: 1;
      min-height: 0;
      overflow: auto;
      padding: 14px;
    }

    .toolbar-row, .row, .stack, .inline-actions {
      display: flex;
      gap: 8px;
      align-items: center;
      flex-wrap: wrap;
    }

    .stack { flex-direction: column; align-items: stretch; }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      min-height: 34px;
      padding: 0 12px;
      border-radius: 10px;
      border: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
      color: var(--foreground-default);
      transition: transform var(--transition-fast), background var(--transition-fast), border-color var(--transition-fast);
    }

    .btn:hover {
      background: var(--background-highest);
      border-color: var(--outline-default);
    }

    .btn:active { transform: translateY(1px); }

    .btn.primary {
      background: var(--accent-primary-default);
      color: white;
      border-color: transparent;
    }

    .btn.primary:hover { background: var(--accent-primary-hover); }
    .btn.ghost { background: transparent; }
    .btn.negative { background: var(--accent-negative-soft); color: hsl(355 95% 78%); }
    .btn.positive { background: var(--accent-positive-soft); color: hsl(138 80% 70%); }

    .field, .select, .textarea {
      width: 100%;
      min-height: 36px;
      padding: 0 10px;
    }

    .textarea {
      min-height: 88px;
      padding: 10px;
      resize: vertical;
    }

    .section {
      padding: 12px;
      border: 1px solid var(--outline-dimmest);
      border-radius: var(--radius-md);
      background: var(--background-higher);
      margin-bottom: 12px;
    }

    .section h3 {
      margin: 0 0 8px 0;
      font-size: 13px;
    }

    .tree {
      display: flex;
      flex-direction: column;
      gap: 2px;
      margin-top: 10px;
    }

    .tree-row {
      display: flex;
      align-items: center;
      gap: 8px;
      min-height: 32px;
      padding: 0 8px;
      border-radius: 8px;
      color: var(--foreground-dimmer);
      transition: background var(--transition-fast), color var(--transition-fast);
    }

    .tree-row:hover { background: var(--background-highest); color: var(--foreground-default); }
    .tree-row.active { background: var(--accent-primary-soft); color: var(--foreground-default); }
    .tree-indent { padding-left: 16px; }

    .folder-children {
      margin-left: 14px;
      border-left: 1px dashed var(--outline-dimmest);
      padding-left: 6px;
    }

    .footer-actions {
      display: grid;
      gap: 8px;
      margin-top: 12px;
    }

    .list {
      display: grid;
      gap: 10px;
    }

    .item-card {
      padding: 10px 12px;
      border-radius: 12px;
      border: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
    }

    .item-card strong { display: block; margin-bottom: 4px; font-size: 13px; }
    .item-meta { color: var(--foreground-dimmer); font-size: 12px; }

    .badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      min-height: 24px;
      padding: 0 10px;
      border-radius: 999px;
      background: var(--accent-primary-soft);
      color: var(--accent-primary-default);
      font-size: 12px;
      font-weight: 600;
    }

    .badge.new { background: var(--accent-blurple-soft); color: var(--accent-blurple-default); }
    .badge.ok { background: var(--accent-positive-soft); color: hsl(138 80% 70%); }
    .badge.warn { background: hsl(47 100% 50% / .12); color: hsl(47 92% 62%); }
    .badge.err { background: var(--accent-negative-soft); color: hsl(355 90% 70%); }

    .search-row {
      display: flex;
      gap: 8px;
      align-items: center;
      margin-bottom: 10px;
    }

    .checkbox-row {
      display: flex;
      align-items: center;
      gap: 8px;
      color: var(--foreground-dimmer);
      font-size: 12px;
    }

    .result-hit {
      padding: 10px 12px;
      border-radius: 10px;
      background: var(--background-higher);
      border: 1px solid var(--outline-dimmest);
      cursor: pointer;
    }

    .result-hit:hover { border-color: var(--outline-default); background: var(--background-highest); }
    .result-line { font-family: var(--mono); font-size: 12px; color: var(--foreground-dimmer); margin-top: 5px; }

    .mask {
      font-family: var(--mono);
      letter-spacing: .06em;
    }

    .progress {
      width: 100%;
      height: 8px;
      overflow: hidden;
      border-radius: 999px;
      background: var(--background-root);
      border: 1px solid var(--outline-dimmest);
    }

    .progress > span {
      display: block;
      height: 100%;
      width: 0%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--accent-primary-default), var(--accent-blurple-default));
      transition: width var(--transition-med);
    }

    .storage-dropzone {
      position: relative;
      min-height: 140px;
      display: grid;
      place-items: center;
      text-align: center;
      border: 1px dashed var(--outline-default);
      border-radius: var(--radius-md);
      background: var(--background-higher);
      color: var(--foreground-dimmer);
    }

    .storage-dropzone.dragover {
      background: var(--accent-primary-soft);
      border-color: var(--accent-primary-default);
      color: var(--foreground-default);
    }

    .storage-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(106px, 1fr));
      gap: 10px;
      margin-top: 12px;
    }

    .storage-file {
      padding: 10px;
      min-height: 92px;
      border-radius: 12px;
      border: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 8px;
    }

    .agent-head {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 14px;
      border-bottom: 1px solid var(--outline-dimmest);
      background: var(--background-default);
    }

    .agent-sub {
      color: var(--foreground-dimmer);
      font-size: 12px;
      margin-top: 4px;
      max-width: 28ch;
    }

    .agent-body {
      flex: 1;
      min-height: 0;
      display: flex;
      flex-direction: column;
      background: var(--background-default);
    }

    .message-thread {
      position: relative;
      flex: 1;
      min-height: 0;
      overflow: auto;
      padding: 16px 14px 84px;
      display: flex;
      flex-direction: column;
      gap: 12px;
      scroll-behavior: smooth;
    }

    .bubble {
      max-width: 92%;
      padding: 12px 13px;
      border-radius: 14px;
      border: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
      box-shadow: var(--shadow-sm);
    }

    .bubble.user {
      align-self: flex-end;
      background: var(--accent-primary-soft);
      border-color: hsl(204 100% 62% / .3);
    }

    .bubble.agent {
      align-self: flex-start;
    }

    .bubble .role {
      display: block;
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: .08em;
      color: var(--foreground-dimmer);
      margin-bottom: 6px;
    }

    .suggestions {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      padding: 0 14px 12px;
    }

    .suggestion {
      padding: 9px 10px;
      border-radius: 999px;
      background: var(--background-higher);
      border: 1px solid var(--outline-dimmest);
      color: var(--foreground-dimmer);
      font-size: 12px;
    }

    .suggestion:hover { color: var(--foreground-default); background: var(--background-highest); }

    .scroll-latest {
      position: absolute;
      right: 18px;
      bottom: 18px;
      z-index: 3;
      padding: 8px 12px;
      border-radius: 999px;
      background: var(--background-highest);
      border: 1px solid var(--outline-default);
      color: var(--foreground-default);
      box-shadow: var(--shadow-md);
      opacity: 0;
      pointer-events: none;
      transform: translateY(10px);
      transition: opacity var(--transition-fast), transform var(--transition-fast);
    }

    .scroll-latest.visible {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0);
    }

    .agent-compose {
      padding: 12px 14px 14px;
      border-top: 1px solid var(--outline-dimmest);
      background: var(--background-default);
    }

    .composer-box {
      padding: 10px;
      border-radius: 14px;
      border: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
    }

    .composer-input {
      min-height: 76px;
      max-height: 180px;
      overflow: auto;
      border: 0;
      background: transparent;
      border-radius: 0;
      padding: 2px 2px 8px;
    }

    .composer-input:empty::before {
      content: "Make, test, iterate…";
      color: var(--foreground-dimmest);
    }

    .composer-toolbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      flex-wrap: wrap;
    }

    .toolbar-left,
    .toolbar-right {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .icon-btn {
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border-radius: 10px;
      background: var(--background-default);
      border: 1px solid var(--outline-dimmest);
      color: var(--foreground-dimmer);
    }

    .icon-btn:hover { color: var(--foreground-default); background: var(--background-highest); }

    .send-btn[disabled] {
      opacity: .45;
      cursor: not-allowed;
      pointer-events: none;
    }

    .bottom-dock {
      height: var(--dock-height);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 0 12px;
      background: var(--background-default);
      border-top: 1px solid var(--outline-dimmest);
    }

    .dock-center {
      display: flex;
      gap: 6px;
      padding: 4px;
      border-radius: 12px;
      background: var(--background-higher);
      border: 1px solid var(--outline-dimmest);
    }

    .dock-tab {
      min-height: 38px;
      padding: 0 12px;
      border-radius: 10px;
      color: var(--foreground-dimmer);
    }

    .dock-tab.active {
      color: var(--foreground-default);
      background: var(--background-default);
      box-shadow: var(--shadow-sm);
    }

    .overlay {
      position: fixed;
      inset: 0;
      z-index: 20;
      background: var(--background-overlay);
      backdrop-filter: blur(12px);
      opacity: 0;
      pointer-events: none;
      transition: opacity var(--transition-med);
    }

    .overlay.open {
      opacity: 1;
      pointer-events: auto;
    }

    .tasks-drawer,
    .command-palette,
    .history-modal,
    .publish-modal {
      position: fixed;
      z-index: 25;
      background: var(--background-default);
      border: 1px solid var(--outline-dimmer);
      box-shadow: var(--shadow-lg);
      opacity: 0;
      pointer-events: none;
      transition: transform var(--transition-med), opacity var(--transition-med);
    }

    .tasks-drawer {
      left: 50%;
      bottom: 16px;
      width: min(920px, calc(100vw - 32px));
      max-height: min(68vh, 700px);
      border-radius: 22px;
      transform: translate(-50%, 30px);
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    .tasks-drawer.open {
      opacity: 1;
      pointer-events: auto;
      transform: translate(-50%, 0);
    }

    .drawer-head, .modal-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 14px 16px;
      border-bottom: 1px solid var(--outline-dimmest);
      background: var(--background-default);
    }

    .drawer-body {
      overflow: auto;
      padding: 16px;
    }

    .segmented {
      display: inline-flex;
      gap: 4px;
      padding: 4px;
      border-radius: 12px;
      background: var(--background-higher);
      border: 1px solid var(--outline-dimmest);
    }

    .segmented button {
      min-height: 34px;
      padding: 0 12px;
      border-radius: 8px;
      color: var(--foreground-dimmer);
    }

    .segmented button.active {
      background: var(--background-default);
      color: var(--foreground-default);
    }

    .timeline {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 10px;
      margin-top: 14px;
    }

    .timeline-step {
      padding: 12px;
      border-radius: 12px;
      border: 1px solid var(--outline-dimmest);
      background: var(--background-higher);
    }

    .timeline-dot {
      width: 12px;
      height: 12px;
      border-radius: 999px;
      margin-bottom: 10px;
    }

    .command-palette {
      top: 12vh;
      left: 50%;
      width: min(720px, calc(100vw - 28px));
      border-radius: 18px;
      transform: translate(-50%, -16px);
      overflow: hidden;
    }

    .command-palette.open,
    .history-modal.open,
    .publish-modal.open {
      opacity: 1;
      pointer-events: auto;
      transform: translate(-50%, 0);
    }

    .command-search {
      width: 100%;
      min-height: 52px;
      border: 0;
      border-radius: 0;
      padding: 0 16px;
      background: transparent;
      font-size: 15px;
    }

    .command-results {
      max-height: 52vh;
      overflow: auto;
      border-top: 1px solid var(--outline-dimmest);
      padding: 8px;
    }

    .command-item {
      width: 100%;
      text-align: left;
      padding: 12px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      color: var(--foreground-default);
    }

    .command-item:hover { background: var(--background-higher); }
    .command-kind { color: var(--foreground-dimmer); font-size: 12px; }

    .history-modal,
    .publish-modal {
      top: 10vh;
      left: 50%;
      width: min(760px, calc(100vw - 24px));
      border-radius: 20px;
      transform: translate(-50%, -18px);
      overflow: hidden;
    }

    .modal-body {
      max-height: 68vh;
      overflow: auto;
      padding: 16px;
    }

    .kpi-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }

    .small {
      font-size: 12px;
      color: var(--foreground-dimmer);
    }

    .pill-toggle {
      width: 42px;
      height: 24px;
      border-radius: 999px;
      background: var(--background-root);
      border: 1px solid var(--outline-dimmest);
      position: relative;
      transition: background var(--transition-fast), border-color var(--transition-fast);
    }

    .pill-toggle::after {
      content: "";
      position: absolute;
      top: 2px;
      left: 2px;
      width: 18px;
      height: 18px;
      border-radius: 50%;
      background: var(--foreground-dimmer);
      transition: transform var(--transition-fast), background var(--transition-fast);
    }

    .pill-toggle.on {
      background: var(--accent-positive-soft);
      border-color: hsl(138 60% 40% / .4);
    }

    .pill-toggle.on::after {
      transform: translateX(18px);
      background: var(--accent-positive-default);
    }

    .hidden { display: none !important; }

    @media (max-width: 1180px) {
      .sidebar-right {
        position: absolute;
        right: 0;
        top: 0;
        bottom: 0;
        z-index: 12;
        box-shadow: var(--shadow-lg);
      }
    }

    @media (max-width: 920px) {
      .sidebar-left {
        position: absolute;
        left: var(--leftbar-width);
        top: 0;
        bottom: 0;
        z-index: 11;
        box-shadow: var(--shadow-lg);
      }
    }

    @media (max-width: 760px) {
      :root {
        --right-sidebar-width: min(100vw - 20px, 390px);
        --left-sidebar-width: min(100vw - 68px, 320px);
      }

      .dock-center { overflow-x: auto; }
      .timeline { grid-template-columns: 1fr; }
      .kpi-grid { grid-template-columns: 1fr; }
    }
  </style>

