      storageFiles: [],
      workflowDraft: { name: '', steps: [] },
      workflows: [
        { id: uid('wf'), name: 'Default run', steps: ['Install dependencies', 'Start runtime', 'Open preview'] },
        { id: uid('wf'), name: 'Test and lint', steps: ['Run linter', 'Run unit tests', 'Report diagnostics'] }
      ],
      skills: [
        { id: 'code-review', label: 'Code review', enabled: true, mode: 'Automatic' },
        { id: 'test-generation', label: 'Test generation', enabled: true, mode: 'Assisted' },
