        }
      ],
      terminal: [
        { type: 'dim', text: 'Workspace initialized.' },
        { type: 'dim', text: 'Type "help" to view available commands.' }
      ]
    };

    const commandDefs = [
      { label: 'Open Files panel', kind: 'Tool', run: () => activateTool('files') },
      { label: 'Open Search panel', kind: 'Tool', run: () => activateTool('search') },
      { label: 'Open Secrets panel', kind: 'Tool', run: () => activateTool('secrets') },
      { label: 'Open Security Center', kind: 'Tool', run: () => activateTool('security') },
      { label: 'Open Workflows', kind: 'Tool', run: () => activateTool('workflows') },
      { label: 'Open Agent Skills', kind: 'Tool', run: () => activateTool('skills') },
      { label: 'Open App Storage', kind: 'Tool', run: () => activateTool('storage') },
      { label: 'Open User Settings', kind: 'Tool', run: () => activateTool('settings') },
      { label: 'Run app', kind: 'Command', run: () => runApp() },
      { label: 'Toggle preview', kind: 'Command', run: () => togglePreview() },
      { label: 'Toggle terminal', kind: 'Command', run: () => toggleTerminal() },
      { label: 'Open tasks drawer', kind: 'Command', run: () => openTasks(true) },
      { label: 'New file', kind: 'Command', run: () => { activateTool('files'); state.pendingCreate = 'file'; renderLeftPanel(); } },
      { label: 'New folder', kind: 'Command', run: () => { activateTool('files'); state.pendingCreate = 'folder'; renderLeftPanel(); } },
      { label: 'New tab', kind: 'Command', run: () => newScratchFile() }
    ];

    const editorThemeCompartment = new Compartment();
    const editorWrapCompartment = new Compartment();
    const editorFontCompartment = new Compartment();
    const editorGutterCompartment = new Compartment();
    const editorLanguageCompartment = new Compartment();
    const editorPlaceholderCompartment = new Compartment();

    let editorView;

    function setTheme(theme) {
      state.themeOverride = theme;
      state.settings.theme = theme;
      const html = document.documentElement;
      if (theme === 'system') html.removeAttribute('data-theme');
      else html.setAttribute('data-theme', theme);
      $('#themeInfo').textContent = theme[0].toUpperCase() + theme.slice(1);
    }

    function currentThemeIsDark() {
      if (state.themeOverride === 'dark') return true;
      if (state.themeOverride === 'light') return false;
      return window.matchMedia('(prefers-color-scheme: dark)').matches;
    }

    function cmTheme() {
      const s = getComputedStyle(document.documentElement);
      return EditorView.theme({
        '&': {
          height: '100%',
          fontSize: `${state.settings.fontSize}px`,
          backgroundColor: s.getPropertyValue('--background-default').trim(),
          color: s.getPropertyValue('--foreground-default').trim()
        },
        '.cm-editor': { height: '100%' },
        '.cm-scroller': {
          fontFamily: 'var(--mono)',
          lineHeight: '1.55',
          padding: '12px 0'
        },
        '.cm-content': { caretColor: s.getPropertyValue('--accent-primary-default').trim() },
        '.cm-cursor, .cm-dropCursor': { borderLeftColor: s.getPropertyValue('--accent-primary-default').trim() },
        '.cm-selectionBackground, .cm-content ::selection': {
          backgroundColor: s.getPropertyValue('--accent-primary-soft').trim()
        },
        '.cm-gutters': {
          backgroundColor: s.getPropertyValue('--background-default').trim(),
          color: s.getPropertyValue('--foreground-dimmest').trim(),
          borderRight: `1px solid ${s.getPropertyValue('--outline-dimmest').trim()}`,
          display: state.settings.lineNumbers ? 'block' : 'none'
        },
        '.cm-activeLine': {
          backgroundColor: s.getPropertyValue('--background-higher').trim()
        },
        '.cm-activeLineGutter': {
          backgroundColor: s.getPropertyValue('--background-higher').trim()
        },
        '.cm-placeholder': {
          color: s.getPropertyValue('--foreground-dimmest').trim()
        },
        '.cm-panels': {
          backgroundColor: s.getPropertyValue('--background-higher').trim(),
          color: s.getPropertyValue('--foreground-default').trim()
        },
        '.cm-tooltip': {
          backgroundColor: s.getPropertyValue('--background-highest').trim(),
          color: s.getPropertyValue('--foreground-default').trim(),
          border: `1px solid ${s.getPropertyValue('--outline-dimmer').trim()}`
        }
      }, { dark: currentThemeIsDark() });
    }

    function getLanguageExtension(fileName = '') {
      const lower = fileName.toLowerCase();
      if (lower.endsWith('.js') || lower.endsWith('.mjs') || lower.endsWith('.cjs') || lower.endsWith('.json')) {
        return javascript();
      }
      return [];
    }

    function flattenFiles(nodes = state.files, depth = 0, out = []) {
      for (const node of nodes) {
        out.push({ ...node, depth });
        if (node.type === 'folder' && node.children?.length) flattenFiles(node.children, depth + 1, out);
      }
      return out;
    }

    function findNode(id, nodes = state.files, parent = null) {
      for (const node of nodes) {
        if (node.id === id) return { node, parent };
        if (node.type === 'folder' && node.children) {
          const found = findNode(id, node.children, node);
          if (found) return found;
        }
      }
      return null;
    }

    function getActiveFile() {
      const found = findNode(state.activeFileId);
      return found?.node || null;
    }

    function saveActiveDoc() {
      const active = getActiveFile();
      if (active && editorView) active.content = editorView.state.doc.toString();
    }

    function openFile(fileId) {
      saveActiveDoc();
      const found = findNode(fileId);
      if (!found || found.node.type !== 'file') return;
      state.activeFileId = fileId;
      if (!state.openTabs.includes(fileId)) state.openTabs.push(fileId);
      refreshEditor();
      renderTabs();
      renderLeftPanel();
      updateEditorStatus();
    }

    function closeTab(fileId) {
      const idx = state.openTabs.indexOf(fileId);
      if (idx === -1) return;
      state.openTabs.splice(idx, 1);
      if (!state.openTabs.length) {
        const firstVisible = flattenFiles().find(f => f.type === 'file');
        if (firstVisible) state.openTabs.push(firstVisible.id);
      }
      if (state.activeFileId === fileId) {
        state.activeFileId = state.openTabs[Math.max(0, idx - 1)] || state.openTabs[0];
        refreshEditor();
      }
      renderTabs();
      renderLeftPanel();
      updateEditorStatus();
    }

    function newScratchFile() {
      const nameBase = `untitled-${Date.now().toString().slice(-4)}.js`;
      const file = {
        id: uid('file'),
        name: nameBase,
        type: 'file',
        hidden: false,
        content: `export function main() {\n  return "${nameBase}";\n}\n`
      };
      state.files.push(file);
      state.openTabs.push(file.id);
      state.activeFileId = file.id;
      renderLeftPanel();
      renderTabs();
      refreshEditor();
      logToTerminal(`Created ${file.name}`, 'ok');
    }

    function addNode(name, type) {
      const trimmed = name.trim();
      if (!trimmed) return;
      const node = type === 'folder'
        ? { id: uid('folder'), name: trimmed, type: 'folder', hidden: trimmed.startsWith('.'), open: true, children: [] }
        : { id: uid('file'), name: trimmed, type: 'file', hidden: trimmed.startsWith('.'), content: '' };
      state.files.push(node);
      state.pendingCreate = null;
      renderLeftPanel();
      if (type === 'file') openFile(node.id);
    }

    function removeSecret(id) {
      state.secrets = state.secrets.filter(s => s.id !== id);
      renderLeftPanel();
    }

    function updateSecretMask(id) {
      const s = state.secrets.find(x => x.id === id);
      if (!s) return;
      s.masked = !s.masked;
      renderLeftPanel();
    }

    function escapeRegExp(str) {
      return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    function searchMatches() {
      const q = state.search.query;
      if (!q.trim()) return [];
      const source = state.search.word ? `\\b${escapeRegExp(q)}\\b` : escapeRegExp(q);
      const flags = state.search.case ? 'g' : 'gi';
      const re = new RegExp(source, flags);
      const hits = [];
      for (const file of flattenFiles().filter(f => f.type === 'file')) {
        const lines = file.content.split('\n');
        lines.forEach((line, i) => {
          if (re.test(line)) hits.push({ fileId: file.id, fileName: file.name, lineNo: i + 1, line });
          re.lastIndex = 0;
        });
      }
      return hits;
    }

    function renderActivityBar() {
      const host = $('#activityButtons');
      host.innerHTML = toolDefs.map(tool => `
        <button class="activity-btn ${state.activeTool === tool.id ? 'active' : ''}" data-tool="${tool.id}" title="${escapeHtml(tool.title)}" aria-label="${escapeHtml(tool.label)}">
          ${tool.icon}
        </button>
      `).join('');
      $('#commandLauncher').innerHTML = icons.command;
      host.addEventListener('click', e => {
        const btn = e.target.closest('[data-tool]');
        if (!btn) return;
        activateTool(btn.dataset.tool);
      });
    }

    function activateTool(id) {
      state.activeTool = id;
      state.leftSidebarOpen = true;
      $('#leftSidebar').classList.remove('collapsed');
      renderActivityBar();
      renderLeftPanel();
    }

    function renderTabs() {
      const host = $('#tabsList');
      host.innerHTML = state.openTabs.map(fileId => {
        const node = findNode(fileId)?.node;
        if (!node) return '';
        return `
          <button class="tab ${state.activeFileId === fileId ? 'active' : ''}" data-file="${fileId}">
            <span class="tab-name">${escapeHtml(node.name)}</span>
            <span class="tab-close" data-close="${fileId}" aria-label="Close tab">${icons.xsmall}</span>
          </button>
        `;
      }).join('');
    }

    function renderSuggestions() {
      $('#suggestions').innerHTML = suggestionPrompts.map(p => `
        <button class="suggestion" data-suggestion="${escapeHtml(p)}">${escapeHtml(p)}</button>
      `).join('');
    }

    function renderMessages() {
      const thread = $('#messageThread');
      thread.innerHTML = state.messages.map(msg => `
        <div class="bubble ${msg.role === 'user' ? 'user' : 'agent'}">
          <span class="role">${msg.role}</span>
          <div>${escapeHtml(msg.text).replaceAll('\n', '<br>')}</div>
        </div>
      `).join('');
      renderHistory();
      requestAnimationFrame(() => scrollMessagesToBottom());
    }

    function renderHistory() {
      $('#historyBody').innerHTML = state.messages.map(msg => `
        <div class="item-card" style="margin-bottom:10px;">
          <strong>${escapeHtml(msg.role)}</strong>
          <div>${escapeHtml(msg.text).replaceAll('\n', '<br>')}</div>
        </div>
      `).join('');
    }

    function renderDock() {
      $('#dockTabs').innerHTML = dockDefs.map(name => `
        <button class="dock-tab ${state.dockMode === name ? 'active' : ''}" data-dock="${name}">${name}</button>
      `).join('');
    }

    function renderTasksTabs() {
      $('#tasksTabs').innerHTML = `
        <button class="${state.taskTab === 'main' ? 'active' : ''}" data-tasktab="main">Main version</button>
        <button class="${state.taskTab === 'new' ? 'active' : ''}" data-tasktab="new">New task</button>
      `;
      $('#taskDynamicArea').innerHTML = state.taskTab === 'main'
        ? `<div class="section"><strong>Main version queue</strong><div class="small" style="margin-top:6px;">No blocking conflicts. Ready for agent merge rehearsal.</div></div>`
        : `<div class="section"><strong>Create a new task</strong><div class="small" style="margin-top:6px;">Fork your current context into a background branch and keep iterating in parallel.</div><div class="row" style="margin-top:12px;"><button class="btn primary" id="spawnTaskBtn">Start background task</button></div></div>`;
    }

    function renderTerminal() {
      $('#terminalLog').innerHTML = state.terminal.map(line => `<div class="terminal-line ${line.type || ''}">${escapeHtml(line.text)}</div>`).join('');
      $('#terminalLog').scrollTop = $('#terminalLog').scrollHeight;
    }

    function logToTerminal(text, type = '') {
      state.terminal.push({ text, type });
      renderTerminal();
    }

    function updateEditorStatus() {
      const active = getActiveFile();
      $('#activeFileLabel').textContent = active?.name || 'No file';
      if (editorView) {
        const doc = editorView.state.doc.toString();
        const lines = doc.split('\n').length;
        const chars = doc.length;
        $('#docStats').textContent = `${lines} lines · ${chars} chars`;
      }
    }

    function editorStateForFile(file) {
      return EditorState.create({
        doc: file?.content ?? '',
        extensions: [
          basicSetup,
          keymap.of([]),
          editorLanguageCompartment.of(getLanguageExtension(file?.name || '')),
          editorThemeCompartment.of(cmTheme()),
          editorWrapCompartment.of(state.settings.wordWrap ? EditorView.lineWrapping : []),
          editorFontCompartment.of(EditorView.theme({ '&': { fontSize: `${state.settings.fontSize}px` } })),
          editorGutterCompartment.of(EditorView.theme({
            '.cm-gutters': { display: state.settings.lineNumbers ? 'block' : 'none' }
          })),
          editorPlaceholderCompartment.of(placeholder('Start building…')),
          EditorView.updateListener.of(update => {
            if (update.docChanged) {
              const active = getActiveFile();
              if (active) active.content = update.state.doc.toString();
              updateEditorStatus();
            }
            if (update.selectionSet || update.docChanged) {
              const pos = update.state.selection.main.head;
              const line = update.state.doc.lineAt(pos);
              $('#cursorInfo').textContent = `Ln ${line.number}, Col ${pos - line.from + 1}`;
            }
          })
        ]
      });
    }

    function createEditor() {
      const host = $('#editorHost');
      const file = getActiveFile();
      editorView = new EditorView({
        state: editorStateForFile(file),
        parent: host
      });
      updateEditorStatus();
    }

    function refreshEditor() {
      if (!editorView) return createEditor();
      const file = getActiveFile();
      editorView.setState(editorStateForFile(file));
      updateEditorStatus();
    }

    function renderFilesPanel() {
      const renderNode = (node, depth = 0) => {
        if (state.hideHidden && node.name.startsWith('.')) return '';
        const isActive = node.id === state.activeFileId;
        if (node.type === 'folder') {
          return `
            <div>
              <button class="tree-row ${isActive ? 'active' : ''}" data-folder="${node.id}">
                ${node.open ? icons.chevrondown : icons.chevron}
                <span>${escapeHtml(node.name)}</span>
              </button>
              <div class="folder-children ${node.open ? '' : 'hidden'}">
                ${(node.children || []).map(child => renderNode(child, depth + 1)).join('')}
              </div>
            </div>
          `;
        }
        return `
          <button class="tree-row ${isActive ? 'active' : ''}" data-open-file="${node.id}">
            <span style="width:18px;"></span>
            <span>${escapeHtml(node.name)}</span>
          </button>
        `;
      };

      const creationInput = state.pendingCreate ? `
        <div class="section">
          <div class="small" style="margin-bottom:8px;">Create new ${state.pendingCreate}</div>
          <input class="field" id="createNodeInput" placeholder="${state.pendingCreate === 'file' ? 'new-file.js' : 'new-folder'}" />
        </div>
      ` : '';

      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>Library</h2>
            <div class="panel-subtle">File tree</div>
          </div>
          <div class="row">
            <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
          </div>
        </div>
        <div class="panel-body">
          ${creationInput}
          <div class="section">
            <div class="row" style="justify-content: space-between;">
              <strong>File tree</strong>
              <span class="small">${flattenFiles().filter(n => n.type === 'file').length} files</span>
            </div>
            <div class="tree">
              ${state.files.map(node => renderNode(node)).join('')}
            </div>
          </div>

          <div class="footer-actions">
            <button class="btn primary" id="newFileBtn">New file</button>
            <button class="btn" id="newFolderBtn">New folder</button>
            <button class="btn" id="uploadFilesBtn">Upload files</button>
            <button class="btn" id="zipBtn">Download as zip</button>
            <button class="btn ghost" id="toggleHiddenBtn">${state.hideHidden ? 'Show hidden files' : 'Hide hidden files'}</button>
          </div>
        </div>
      `;
    }

    function renderSearchPanel() {
      const hits = searchMatches();
      const fileCount = new Set(hits.map(h => h.fileId)).size;
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>Search</h2>
            <div class="panel-subtle">Search through your files</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="section">
            <input class="field" id="searchInput" placeholder="Search project content…" value="${escapeHtml(state.search.query)}" />
            <div class="search-row" style="margin-top:10px;">
              <label class="checkbox-row"><input type="checkbox" id="matchCaseToggle" ${state.search.case ? 'checked' : ''}/> Match case</label>
              <label class="checkbox-row"><input type="checkbox" id="wholeWordToggle" ${state.search.word ? 'checked' : ''}/> Match word</label>
            </div>
            <div class="small">${hits.length ? `${hits.length} matches across ${fileCount} files` : 'No matches yet'}</div>
          </div>
          <div class="list">
            ${hits.map(hit => `
              <button class="result-hit" data-jump-file="${hit.fileId}">
                <strong>${escapeHtml(hit.fileName)} · line ${hit.lineNo}</strong>
                <div class="result-line">${escapeHtml(hit.line.trim() || ' ')}</div>
              </button>
            `).join('') || '<div class="small">Type a query to search all editable files.</div>'}
          </div>
        </div>
      `;
    }

    function renderSecretsPanel() {
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>Secrets</h2>
            <div class="panel-subtle">Store sensitive information securely in your App</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="section">
            <div class="stack">
              <input class="field" id="secretKeyInput" placeholder="KEY_NAME" />
              <input class="field" id="secretValueInput" placeholder="Secret value" />
              <div class="row" style="justify-content: space-between;">
                <label class="checkbox-row"><input type="checkbox" id="secretMaskToggle" checked /> Mask value</label>
                <button class="btn primary" id="saveSecretBtn">Save secret</button>
              </div>
            </div>
          </div>
          <div class="list">
            ${state.secrets.map(secret => `
              <div class="item-card">
                <strong>${escapeHtml(secret.key)}</strong>
