                <div class="row" style="margin-top:10px;">
                  <button class="btn ghost" data-mask-secret="${secret.id}">${secret.masked ? 'Reveal' : 'Mask'}</button>
                  <button class="btn negative" data-delete-secret="${secret.id}">Delete</button>
                </div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    function renderSecurityPanel() {
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>Security Center</h2>
            <div class="panel-subtle">Find, fix, and monitor security vulnerabilities and privacy issues</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="section">
            <div class="kpi-grid">
              <div class="item-card"><strong>Dependency health</strong><span class="badge ok">Stable</span></div>
              <div class="item-card"><strong>Runtime policy</strong><span class="badge">Sandboxed</span></div>
              <div class="item-card"><strong>Secrets exposure</strong><span class="badge ok">Protected</span></div>
              <div class="item-card"><strong>Privacy profile</strong><span class="badge warn">Review rules</span></div>
            </div>
          </div>

          <div class="section">
            <div class="row" style="justify-content: space-between;">
              <strong>Vulnerability scan</strong>
              <button class="btn primary" id="scanBtn">${state.scanActive ? 'Scanning…' : 'Run scan'}</button>
            </div>
            <div class="progress" style="margin-top:12px;"><span style="width:${state.scanProgress}%"></span></div>
            <div class="small" style="margin-top:8px;">${state.scanActive ? `Scanning workspace… ${state.scanProgress}%` : 'Ready for a new scan'}</div>
          </div>

          <div class="section">
            <strong>Privacy rules</strong>
            <div class="list" style="margin-top:10px;">
              ${state.privacyToggles.map(item => `
                <div class="item-card">
                  <div class="row" style="justify-content: space-between;">
                    <div>
                      <strong>${escapeHtml(item.label)}</strong>
                      <div class="small">${item.on ? 'Enabled policy' : 'Disabled policy'}</div>
                    </div>
                    <button class="pill-toggle ${item.on ? 'on' : ''}" data-privacy-toggle="${item.id}" aria-label="Toggle ${escapeHtml(item.label)}"></button>
                  </div>
                </div>
              `).join('')}
            </div>
          </div>
        </div>
      `;
    }

    function renderWorkflowsPanel() {
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>Workflows</h2>
            <div class="panel-subtle">Configure different ways to run your App</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="section">
            <strong>Build workflow</strong>
            <div class="stack" style="margin-top:10px;">
              <input class="field" id="workflowNameInput" placeholder="Workflow name" value="${escapeHtml(state.workflowDraft.name)}" />
              <div class="row">
                <input class="field" id="workflowStepInput" placeholder="Add run step" />
                <button class="btn" id="addWorkflowStepBtn">Add step</button>
              </div>
              <div class="list">
                ${(state.workflowDraft.steps || []).map((step, idx) => `
                  <div class="item-card">
                    <strong>Step ${idx + 1}</strong>
                    <div class="small">${escapeHtml(step)}</div>
                  </div>
                `).join('') || '<div class="small">No draft steps yet.</div>'}
              </div>
              <button class="btn primary" id="saveWorkflowBtn">Save workflow</button>
            </div>
          </div>

          <div class="list">
            ${state.workflows.map(wf => `
              <div class="item-card">
                <strong>${escapeHtml(wf.name)}</strong>
                <div class="small">${wf.steps.join(' → ')}</div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    function renderSkillsPanel() {
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>Agent Skills</h2>
            <div class="panel-subtle">Manage skills that extend Agent capabilities</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="list">
            ${state.skills.map(skill => `
              <div class="item-card">
                <div class="row" style="justify-content: space-between; align-items:flex-start;">
                  <div>
                    <strong>${escapeHtml(skill.label)}</strong>
                    <div class="small">Mode: ${escapeHtml(skill.mode)}</div>
                  </div>
                  <button class="pill-toggle ${skill.enabled ? 'on' : ''}" data-skill-toggle="${skill.id}" aria-label="Toggle ${escapeHtml(skill.label)}"></button>
                </div>
                <div class="row" style="margin-top:10px;">
                  <select class="field" data-skill-mode="${skill.id}">
                    <option ${skill.mode === 'Automatic' ? 'selected' : ''}>Automatic</option>
                    <option ${skill.mode === 'Assisted' ? 'selected' : ''}>Assisted</option>
                    <option ${skill.mode === 'Manual' ? 'selected' : ''}>Manual</option>
                  </select>
                </div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    function renderStoragePanel() {
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>App Storage</h2>
            <div class="panel-subtle">Host and save uploads like images, videos, and documents</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="storage-dropzone" id="storageDropzone">
            <div>
              <strong>Drop files here</strong>
              <div class="small" style="margin-top:6px;">or click to upload into hosted storage</div>
            </div>
          </div>
          <div class="storage-grid">
            ${state.storageFiles.map(file => `
              <div class="storage-file">
                <strong>${escapeHtml(file.name)}</strong>
                <div class="small">${escapeHtml(file.type || 'file')} · ${formatBytes(file.size)}</div>
              </div>
            `).join('') || '<div class="small" style="grid-column:1/-1;">No uploaded files yet.</div>'}
          </div>
        </div>
      `;
    }

    function renderSettingsPanel() {
      return `
        <div class="panel-head">
          <div class="panel-title">
            <h2>User Settings</h2>
            <div class="panel-subtle">Configure personal editor preferences and workspace settings which apply to all Apps</div>
          </div>
          <button class="icon-btn" id="collapseLeftBtn" title="Collapse sidebar" aria-label="Collapse sidebar">${icons.close}</button>
        </div>
        <div class="panel-body">
          <div class="section">
            <div class="stack">
              <label class="small">Font size</label>
              <input type="range" id="fontSizeInput" min="12" max="20" value="${state.settings.fontSize}" />
              <div class="small">${state.settings.fontSize}px</div>
            </div>
          </div>
          <div class="section">
            <div class="stack">
              <label class="small">Theme override</label>
              <select id="themeSelect" class="field">
                <option value="system" ${state.settings.theme === 'system' ? 'selected' : ''}>System</option>
                <option value="dark" ${state.settings.theme === 'dark' ? 'selected' : ''}>Dark</option>
                <option value="light" ${state.settings.theme === 'light' ? 'selected' : ''}>Light</option>
              </select>
            </div>
          </div>
          <div class="section">
            <div class="stack">
              <label class="checkbox-row"><input type="checkbox" id="wordWrapToggle" ${state.settings.wordWrap ? 'checked' : ''}/> Word wrapping</label>
              <label class="checkbox-row"><input type="checkbox" id="lineNumbersToggle" ${state.settings.lineNumbers ? 'checked' : ''}/> Line numbers</label>
            </div>
          </div>
        </div>
      `;
    }

    function renderLeftPanel() {
      const map = {
        files: renderFilesPanel,
        search: renderSearchPanel,
        secrets: renderSecretsPanel,
        security: renderSecurityPanel,
        workflows: renderWorkflowsPanel,
        skills: renderSkillsPanel,
        storage: renderStoragePanel,
        settings: renderSettingsPanel
      };
      $('#leftPanel').innerHTML = map;
      bindLeftPanelEvents();
    }

    function bindLeftPanelEvents() {
      $('#collapseLeftBtn')?.addEventListener('click', () => {
        state.leftSidebarOpen = false;
        $('#leftSidebar').classList.add('collapsed');
      });

      $('#newFileBtn')?.addEventListener('click', () => { state.pendingCreate = 'file'; renderLeftPanel(); });
      $('#newFolderBtn')?.addEventListener('click', () => { state.pendingCreate = 'folder'; renderLeftPanel(); });

      $('#createNodeInput')?.addEventListener('keydown', e => {
        if (e.key === 'Enter') addNode(e.target.value, state.pendingCreate);
        if (e.key === 'Escape') { state.pendingCreate = null; renderLeftPanel(); }
      });

      $$('#leftPanel [data-folder]').forEach(btn => {
        btn.addEventListener('click', () => {
          const found = findNode(btn.dataset.folder);
          if (!found) return;
          found.node.open = !found.node.open;
          renderLeftPanel();
        });
      });

      $$('#leftPanel [data-open-file]').forEach(btn => {
        btn.addEventListener('click', () => openFile(btn.dataset.openFile));
      });

      $('#uploadFilesBtn')?.addEventListener('click', () => $('#fileUploader').click());
      $('#zipBtn')?.addEventListener('click', () => {
        logToTerminal('Packaging workspace into zip archive…', 'dim');
        setTimeout(() => logToTerminal('Archive generated: library-workspace.zip (simulation)', 'ok'), 600);
      });
      $('#toggleHiddenBtn')?.addEventListener('click', () => {
        state.hideHidden = !state.hideHidden;
        renderLeftPanel();
      });

      $('#searchInput')?.addEventListener('input', e => {
        state.search.query = e.target.value;
        renderLeftPanel();
      });
      $('#matchCaseToggle')?.addEventListener('change', e => {
        state.search.case = e.target.checked;
        renderLeftPanel();
      });
      $('#wholeWordToggle')?.addEventListener('change', e => {
        state.search.word = e.target.checked;
        renderLeftPanel();
      });

      $$('#leftPanel [data-jump-file]').forEach(btn => btn.addEventListener('click', () => openFile(btn.dataset.jumpFile)));

      $('#saveSecretBtn')?.addEventListener('click', () => {
        const key = $('#secretKeyInput').value.trim();
        const value = $('#secretValueInput').value;
        const masked = $('#secretMaskToggle').checked;
        if (!key || !value) return;
        state.secrets.unshift({ id: uid('secret'), key, value, masked });
        renderLeftPanel();
      });

      $$('#leftPanel [data-mask-secret]').forEach(btn => btn.addEventListener('click', () => updateSecretMask(btn.dataset.maskSecret)));
      $$('#leftPanel [data-delete-secret]').forEach(btn => btn.addEventListener('click', () => removeSecret(btn.dataset.deleteSecret)));

      $('#scanBtn')?.addEventListener('click', runSecurityScan);
      $$('#leftPanel [data-privacy-toggle]').forEach(btn => btn.addEventListener('click', () => {
        const item = state.privacyToggles.find(x => x.id === btn.dataset.privacyToggle);
        if (!item) return;
        item.on = !item.on;
        renderLeftPanel();
      }));
